mapper.select:
SELECT cp.id, cp.product_id, cp.source, cp.source_type, COALESCE(cp.price_set_name, ps.name, 'Default Price Set') AS price_set_name, cp.start_date, cp.end_date, cp.quantity, cp.capped_price, p.name AS product_name, p.cost, pp.id AS price_id, pp.price AS current_price FROM capped_price cp INNER JOIN product p ON p.id = cp.product_id AND p.deleted_at IS NULL LEFT JOIN ( SELECT pp1.* FROM product_price pp1 INNER JOIN ( SELECT product_id, MIN(id) AS min_id FROM product_price GROUP BY product_id ) first_pp ON first_pp.min_id = pp1.id ) pp ON pp.product_id = p.id LEFT JOIN price_set ps ON ps.id = pp.price_set_id
cp.source_type = #{q.sourceType}
ORDER BY cp.id DESC
LIMIT #{q.size} OFFSET #{q.offset}
